/* ============================================================
   英語情境單字資料庫  (20 天 / 每天 200 字 / 共 4000 字)
   欄位：w=單字或片語  m=中文意思  e=英文例句  ec=例句中文
   想加天：照 addDay({...}) 格式往下加，最後 DAYS 會自動排序。
   ============================================================ */
const DAYS = [];
function addDay(d){ DAYS.push(d); }

